	--DECLARE @p_program_id			NVARCHAR(100)		= N'SCP0106';
	--DECLARE @p_sheet_name			NVARCHAR(100)		= N'1ST_CUTOFF_LINE';
 --   DECLARE @p_user_id				NVARCHAR(30)		= N'iamarock';
 --   DECLARE @debug_mode				NVARCHAR(1)			= N'F';



	--DECLARE @test_mode                          NVARCHAR(20)		= N'F';
	DECLARE @test_mode                          NVARCHAR(20)	= N'T';


	DECLARE @V_ELAPSED_TIME_BEG     DATETIME                = CURRENT_TIMESTAMP;


	-- LOG 용 변수 설정
    DECLARE @v_program_name NVARCHAR(150)	= 'SCP0106_SAVE_CAPA_LOSS_PLAN_LINE_ASSEMBLY';
    DECLARE @v_log_type     NVARCHAR(30); -- START/END/ERROR/...
    DECLARE @n_log_count    INTEGER			= 0;
    DECLARE @v_log_message  NVARCHAR(1000);
    DECLARE @v_description  NVARCHAR(500);
    DECLARE @d_event_date   DATETIME;


	-- 트렌젝션 시작
	BEGIN TRAN;

	BEGIN TRY
		-- 시작 LOG
		SET @v_log_type						= 'START';
		SET @v_log_message					= '########## Start of procedure ##########';
		SET @v_description					= '';
		SET @d_event_date					= SYSDATETIME();

        IF @test_mode <> 'T'
        BEGIN
		    EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
        END


		DECLARE @v_delimiter				NVARCHAR(1) = '^'

		DECLARE @v_all_cnt		        INTEGER		= 0;
		DECLARE @v_cnt					INTEGER		= 0;

		SET @v_all_cnt = [dbo].[SCM_ARR_SPL_CNT](@p_division_id, @v_delimiter);

        PRINT CONCAT('@v_all_cnt : ', @v_all_cnt);


        PRINT N'속도 이슈로 Unpivot 을 UI 에서 DB 로 이전 BEGIN *******************************************************************************************************'
        BEGIN
			IF OBJECT_ID('tempdb..#T_SCP0106_DATE_COLUMNS') IS NOT NULL
				DROP TABLE #T_SCP0106_DATE_COLUMNS;

			SELECT    NR
					, COLUMN_NAME
					, COLUMN_VALUE
			INTO    #T_SCP0106_DATE_COLUMNS
			FROM    (
						SELECT    A.TOKEN AS COLUMN_NAME
								, B.TOKEN AS COLUMN_VALUE
								, A.NR
						FROM   dbo.String_Split(@p_date_column_names, '^') A
							JOIN (SELECT TOKEN, NR FROM dbo.String_Split(@p_date_column_values, '^')) B ON
									A.NR = B.NR
					) A
			WHERE   1=1
				AND A.COLUMN_NAME <> '';

			PRINT CONCAT('ELAPSED_TIME-#T_SCP0106_DATE_COLUMNS : ', CONVERT(VARCHAR, CURRENT_TIMESTAMP - @V_ELAPSED_TIME_BEG, 114));SET @V_ELAPSED_TIME_BEG = CURRENT_TIMESTAMP;

--TESTING : NOK
--select * from #T_SCP0106_DATE_COLUMNS;return;


			IF OBJECT_ID('tempdb..#T_SCP0106_DATE_VALUES_TEMP') IS NOT NULL
				DROP TABLE #T_SCP0106_DATE_VALUES_TEMP;

			SELECT    CONVERT(INT, NULL)            AS ROW_NR
					, CONVERT(INT, NULL)            AS COL_NR
					, CONVERT(NVARCHAR(30),  NULL)  AS COL_NAME
					, CONVERT(NVARCHAR(100), NULL)  AS COL_VALUE
			INTO    #T_SCP0106_DATE_VALUES_TEMP
			WHERE   1<>1;

			IF CURSOR_STATUS('global','CUR_SCP0106_DATE_COLUMNS') >= -1
			BEGIN
				IF CURSOR_STATUS('global','CUR_SCP0106_DATE_COLUMNS') > -1
				BEGIN
					CLOSE CUR_SCP0106_DATE_COLUMNS
				END

				DEALLOCATE CUR_SCP0106_DATE_COLUMNS
			END

			DECLARE @v_nr                       INT                 = 0;
			DECLARE @v_column_names          	NVARCHAR(MAX)		= N'';
			DECLARE @v_column_values          	NVARCHAR(MAX)		= N'';

			DECLARE CUR_SCP0106_DATE_COLUMNS CURSOR FOR
			SELECT    NR
					, COLUMN_NAME
					, COLUMN_VALUE
			FROM    #T_SCP0106_DATE_COLUMNS;

			OPEN CUR_SCP0106_DATE_COLUMNS;
			FETCH NEXT FROM CUR_SCP0106_DATE_COLUMNS INTO @v_nr, @v_column_names, @v_column_values

			WHILE @@FETCH_STATUS = 0
			BEGIN
				INSERT INTO #T_SCP0106_DATE_VALUES_TEMP
				SELECT    A.ROW_NR
						, A.COL_NR
						, A.COL_NAME
						, B.COL_VALUE
				FROM    (
							SELECT    @v_nr             AS ROW_NR
									, NR                AS COL_NR
									, TOKEN             AS COL_NAME
							FROM    dbo.String_Split(@v_column_names, ';')
						) A
						JOIN
						(
							SELECT    @v_nr             AS ROW_NR
									, NR                AS COL_NR
									, TOKEN             AS COL_VALUE
							FROM    dbo.String_Split(@v_column_values, ';')
						) B ON
								A.ROW_NR = B.ROW_NR
							AND A.COL_NR = B.COL_NR
				WHERE   1=1
					AND COL_NAME IS NOT NULL AND COL_NAME <> ''

				FETCH NEXT FROM CUR_SCP0106_DATE_COLUMNS INTO @v_nr, @v_column_names, @v_column_values
			END

			CLOSE CUR_SCP0106_DATE_COLUMNS;
			DEALLOCATE CUR_SCP0106_DATE_COLUMNS;

			PRINT CONCAT('ELAPSED_TIME-#T_SCP0106_DATE_VALUES_TEMP : ', CONVERT(VARCHAR, CURRENT_TIMESTAMP - @V_ELAPSED_TIME_BEG, 114));SET @V_ELAPSED_TIME_BEG = CURRENT_TIMESTAMP;

			--TESTING : NOK
			--select * from #T_SCP0106_DATE_VALUES_TEMP;return;


			IF OBJECT_ID('tempdb..#T_SCP0106_DATE_VALUES') IS NOT NULL
				DROP TABLE #T_SCP0106_DATE_VALUES;

			SELECT    A.ROW_NR
					, A.YYYYMM
					, A.COL_VALUE AS QTY
			INTO    #T_SCP0106_DATE_VALUES
			FROM    (
						SELECT    ROW_NR
                                , COL_NR
								, COL_NAME
								, COL_VALUE
								, REPLACE(REPLACE(REPLACE(COL_NAME, 'M_00', ''), 'M_01', ''), 'Y_', '') AS YYYYMM
						FROM    #T_SCP0106_DATE_VALUES_TEMP
						WHERE   1=1
							AND (SUBSTRING(COL_NAME, 3, 2) = '01' OR SUBSTRING(COL_NAME, 1, 2) = 'Y_')
					) A

			PRINT CONCAT('ELAPSED_TIME-#T_SCP0106_DATE_VALUES : ', CONVERT(VARCHAR, CURRENT_TIMESTAMP - @V_ELAPSED_TIME_BEG, 114));SET @V_ELAPSED_TIME_BEG = CURRENT_TIMESTAMP;

--TESTING : NOK
--select * from #T_SCP0106_DATE_VALUES;return;

		    IF OBJECT_ID('tempdb..#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_TEMP') IS NOT NULL
			    DROP TABLE #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_TEMP;

            SELECT    @p_version                                        AS VER_ID
                    , @p_version_seq                                    AS VER_SEQ
                    , P1.TOKEN                                          AS DIVISION_ID
                    , P2.TOKEN                                          AS COMPANY_ID
                    , P3.TOKEN                                          AS SITE_ID
                    , P4.TOKEN                                          AS PLANT_ID
                    , P5.TOKEN                                          AS FACTORY_ID
                    , P6.TOKEN                                          AS LINE_ID
                    , P7.TOKEN                                          AS OPERATION_ID
                    , P8.TOKEN                                          AS ELTR_LN_TP_CD
                    , P9.TOKEN                                          AS MDL_NM
                    , P10.TOKEN                                         AS MSR_GR_CD
                    , P11.TOKEN                                         AS MSR_TP_CD
                    , A.YYYYMM                                          AS YYYYMM
                    , A.QTY                                             AS MSR_NVL
					, @p_user_id                                        AS CREATED_BY
					, SYSDATETIME()                                     AS CREATION_DATE
                    , @p_user_id                                        AS LAST_UPDATED_BY
                    , SYSDATETIME()                                     AS LAST_UPDATE_DATE
			INTO    #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_TEMP
			FROM    #T_SCP0106_DATE_VALUES A
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_division_id,      '^')) P1  ON A.ROW_NR = P1.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_company_id,       '^')) P2  ON A.ROW_NR = P2.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_site_id,          '^')) P3  ON A.ROW_NR = P3.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_plant_id,         '^')) P4  ON A.ROW_NR = P4.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_factory_id,       '^')) P5  ON A.ROW_NR = P5.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_line_id,          '^')) P6  ON A.ROW_NR = P6.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_operation_id,     '^')) P7  ON A.ROW_NR = P7.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_electrode_type,   '^')) P8  ON A.ROW_NR = P8.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_nick_name,        '^')) P9  ON A.ROW_NR = P9.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_measure_group,    '^')) P10 ON A.ROW_NR = P10.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_measure,          '^')) P11 ON A.ROW_NR = P11.NR
            WHERE   1<>1;

			INSERT INTO #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_TEMP
            SELECT    @p_version                                        AS VER_ID
                    , @p_version_seq                                    AS VER_SEQ
                    , P1.TOKEN                                          AS DIVISION_ID
                    , P2.TOKEN                                          AS COMPANY_ID
                    , P3.TOKEN                                          AS SITE_ID
                    , P4.TOKEN                                          AS PLANT_ID
                    , P5.TOKEN                                          AS FACTORY_ID
                    , P6.TOKEN                                          AS LINE_ID
                    , P7.TOKEN                                          AS OPERATION_ID
                    , P8.TOKEN                                          AS ELTR_LN_TP_CD
                    , P9.TOKEN                                          AS MDL_NM
                    , P10.TOKEN                                         AS MSR_GR_CD
                    , P11.TOKEN                                         AS MSR_TP_CD
                    , A.YYYYMM                                          AS YYYYMM
                    , A.QTY                                             AS MSR_NVL
					, @p_user_id                                        AS CREATED_BY
					, SYSDATETIME()                                     AS CREATION_DATE
                    , @p_user_id                                        AS LAST_UPDATED_BY
                    , SYSDATETIME()                                     AS LAST_UPDATE_DATE
			FROM    #T_SCP0106_DATE_VALUES A
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_division_id,      '^')) P1  ON A.ROW_NR = P1.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_company_id,       '^')) P2  ON A.ROW_NR = P2.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_site_id,          '^')) P3  ON A.ROW_NR = P3.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_plant_id,         '^')) P4  ON A.ROW_NR = P4.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_factory_id,       '^')) P5  ON A.ROW_NR = P5.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_line_id,          '^')) P6  ON A.ROW_NR = P6.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_operation_id,     '^')) P7  ON A.ROW_NR = P7.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_electrode_type,   '^')) P8  ON A.ROW_NR = P8.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_nick_name,        '^')) P9  ON A.ROW_NR = P9.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_measure_group,    '^')) P10 ON A.ROW_NR = P10.NR
					JOIN (SELECT NR, TOKEN FROM dbo.String_Split(@p_measure,          '^')) P11 ON A.ROW_NR = P11.NR

			PRINT CONCAT('ELAPSED_TIME-#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_TEMP : ', CONVERT(VARCHAR, CURRENT_TIMESTAMP - @V_ELAPSED_TIME_BEG, 114));SET @V_ELAPSED_TIME_BEG = CURRENT_TIMESTAMP;

--TESTING : NOK
--select * from #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_TEMP where YYYYMM = '202405';return;
--select * from #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_TEMP;return;


		    IF OBJECT_ID('tempdb..#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_RAW') IS NOT NULL
			    DROP TABLE #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_RAW;

            --빈테이블 만들기
		    SELECT	  VER_ID
                    , VER_SEQ
                    , DIVISION_ID
                    , COMPANY_ID
                    , SITE_ID
                    , PLANT_ID
                    , FACTORY_ID
                    , LINE_ID
                    , OPERATION_ID
                    , ELTR_LN_TP_CD
            	    , MDL_NM
	                , MSR_GR_CD
                    , MSR_TP_CD
                    , YYYYMM
                    , CONVERT(FLOAT, NULL)                AS MSR_NVL
                    , CREATED_BY
                    , CREATION_DATE
                    , LAST_UPDATED_BY
                    , LAST_UPDATE_DATE
		    INTO	#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_RAW
		    FROM	#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_TEMP
		    WHERE	1<>1;

			INSERT INTO #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_RAW
            SELECT    A.VER_ID
                    , A.VER_SEQ
                    , A.DIVISION_ID
                    , A.COMPANY_ID
                    , A.SITE_ID
                    , A.PLANT_ID
                    , A.FACTORY_ID
                    , A.LINE_ID
                    , A.OPERATION_ID
                    , A.ELTR_LN_TP_CD
                    , A.MDL_NM
                    , A.MSR_GR_CD
                    , A.MSR_TP_CD
                    , A.YYYYMM
                    , CASE
                        WHEN A.MSR_NVL IS NULL OR (RTRIM(LTRIM(A.MSR_NVL))  = '') THEN 0.0
                        ELSE CONVERT(FLOAT, A.MSR_NVL)
                        END AS MSR_NVL
					, A.CREATED_BY
					, A.CREATION_DATE
                    , A.LAST_UPDATED_BY
                    , A.LAST_UPDATE_DATE
			FROM    #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_TEMP A;

			PRINT CONCAT('ELAPSED_TIME#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_RAW : ', CONVERT(VARCHAR, CURRENT_TIMESTAMP - @V_ELAPSED_TIME_BEG, 114));SET @V_ELAPSED_TIME_BEG = CURRENT_TIMESTAMP;

--TESTING : NOK
--select * from #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_RAW where YYYYMM = '202505';rollback tran; return;


		    IF OBJECT_ID('tempdb..#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL') IS NOT NULL
			    DROP TABLE #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL;

            --빈테이블 만들기
		    SELECT	  VER_ID
                    , VER_SEQ
                    , DIVISION_ID
                    , COMPANY_ID
                    , SITE_ID
                    , PLANT_ID
                    , FACTORY_ID
                    , LINE_ID
                    , OPERATION_ID
                    , ELTR_LN_TP_CD
            	    , MDL_NM
	                , MSR_GR_CD
                    , MSR_TP_CD
                    , YYYYMM
	                , MSR_NVL
                    , CREATED_BY
                    , CREATION_DATE
                    , LAST_UPDATED_BY
                    , LAST_UPDATE_DATE
		    INTO	#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL
		    FROM	#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_RAW
		    WHERE	1<>1;

		    INSERT INTO #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL
		    SELECT	  VER_ID
                    , VER_SEQ
