				AND A.PLANT_ID				= B.PLANT_ID
				AND A.FACTORY_ID			= B.FACTORY_ID
				AND A.LINE_ID				= B.LINE_ID
--SCP생산계획 입력은 공정, 라인타입 무시하고 모든 공정에 적용				    AND A.OPERATION_ID			= B.OPERATION_ID
--SCP생산계획 입력은 공정, 라인타입 무시하고 모든 공정에 적용				    AND A.ELTR_LN_TP_CD			= B.ELTR_LN_TP_CD
				AND A.MDL_NM				= B.MDL_NM
				AND A.MSR_GR_CD				= B.MSR_GR_CD
				AND A.MSR_TP_CD				= B.MSR_TP_CD
				AND A.YYYYMM				= B.YYYYMM
			)
			WHEN MATCHED THEN
			UPDATE
			SET
--SCP생산계획 입력은 실적, BASE, 개선율 없음				      PFRSLT_NVL			= B.PFRSLT_NVL
--SCP생산계획 입력은 실적, BASE, 개선율 없음				    , BASE_NVL				= B.BASE_NVL
--SCP생산계획 입력은 실적, BASE, 개선율 없음				    , IPRV_GOL_RT			= B.IPRV_GOL_RT
				    MSR_DDN				= B.MSR_NVL
				, LAST_UPDATED_BY		= B.LAST_UPDATED_BY
				, LAST_UPDATE_DATE		= B.LAST_UPDATE_DATE
			WHEN NOT MATCHED THEN
			INSERT
			(
					VER_ID
				, VER_SEQ
				, DIVISION_ID                 
				, COMPANY_ID                  
				, SITE_ID                     
				, PLANT_ID                    
				, FACTORY_ID                  
				, LINE_ID                     
				, OPERATION_ID                
				, ELTR_LN_TP_CD               
				, MDL_NM                      
				, MSR_GR_CD                   
				, MSR_TP_CD                   
				--, IPRV_GOL_DIVS_CD            -- Improvement Rate 입력 영역을 제거하고 Operation Plan 에 Goal 직접 입력 형태로 수정(2025-02-10 mrchois)
				, YYYYMM                      
--SCP생산계획 입력은 실적, BASE, 개선율 없음				    , PFRSLT_NVL                  
--SCP생산계획 입력은 실적, BASE, 개선율 없음					, BASE_NVL                    
--SCP생산계획 입력은 실적, BASE, 개선율 없음					, IPRV_GOL_RT                 
				, MSR_DDN                     
				, CREATED_BY
				, CREATION_DATE
				, LAST_UPDATED_BY
				, LAST_UPDATE_DATE
			)
			VALUES
			(
				  B.VER_ID
				, B.VER_SEQ
				, B.DIVISION_ID               
				, B.COMPANY_ID                
				, B.SITE_ID                   
				, B.PLANT_ID                  
				, B.FACTORY_ID                
				, B.LINE_ID                   
				, B.OPERATION_ID              
				, B.ELTR_LN_TP_CD             
				, B.MDL_NM                    
				, B.MSR_GR_CD                 
				, B.MSR_TP_CD                 
				--, B.IPRV_GOL_DIVS_CD        -- Improvement Rate 입력 영역을 제거하고 Operation Plan 에 Goal 직접 입력 형태로 수정(2025-02-10 mrchois)  
				, B.YYYYMM                    
--SCP생산계획 입력은 실적, BASE, 개선율 없음				    , B.PFRSLT_NVL                
--SCP생산계획 입력은 실적, BASE, 개선율 없음				    , B.BASE_NVL                  
--SCP생산계획 입력은 실적, BASE, 개선율 없음				    , B.IPRV_GOL_RT               
				, B.MSR_NVL                   
				, B.CREATED_BY                
				, B.CREATION_DATE             
				, B.LAST_UPDATED_BY           
				, B.LAST_UPDATE_DATE          
			);
		END --데이터 저장 - 모델별 - SCP_PROD_PLAN_DDN
--TESTING : NOK
--select * from SCP_MST_CAPA_LOSS_PLAN_LN;
--select * from SCP_MST_CAPA_LOSS_PLAN_MDL_CUTF;rollback tran;return;



        -- LOG end
		SET @v_log_type     = 'END'
		SET @v_log_message  = '########## END of procedure ##########'
		SET @v_description  = ''
		SET @d_event_date   = SYSDATETIME()

        EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date


		COMMIT TRAN;

		-- 결과코드, 결과 카운트 반환
		SELECT  'S' AS result_code,  @v_all_cnt AS result_cnt;
	END TRY
	BEGIN CATCH
		  IF (XACT_STATE() <> 0) ROLLBACK TRAN; --입력 데이타 롤백 처리
		  BEGIN
			INSERT INTO SCM_SYS_LOG_BATCH
			(
				  PROGRAM_NAME
				, LOG_TYPE
				, LOG_COUNT
				, LOG_MESSAGE
				, DESCRIPTION
				, EVENT_DATE
				, CREATION_DATE
				, CREATED_BY
				, LAST_UPDATE_DATE
				, LAST_UPDATED_BY
			)
			VALUES
			(
				  ISNULL(ERROR_PROCEDURE(), 'SCP0006_SAVE_PROJECT_ROUTE_PLANT')
	 			, 'ERROR'
	 			, NULL
	 			, ERROR_MESSAGE()
	 			, NULL
	 			, SYSDATETIME()
	 			, SYSDATETIME()
	 			, ERROR_PROCEDURE()
	 			, SYSDATETIME()
				, ERROR_PROCEDURE()
			)

			--IF @@TRANCOUNT > 0
			--  COMMIT WORK;
		  END;


		  -- error코드, errror 메시지 반환
		  SELECT 'F' AS result_code;

		  SELECT '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE();
	END CATCH;


    BEGIN -- 커서 해제 & 임시테이블 삭제------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		IF OBJECT_ID('tempdb..#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_LN') IS NOT NULL
			DROP TABLE #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_LN;
		IF OBJECT_ID('tempdb..#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL') IS NOT NULL
			DROP TABLE #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL;
		IF OBJECT_ID('tempdb..#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL') IS NOT NULL
			DROP TABLE #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL;
	END
END

